import { LANG_STRINGS } from '../../../../lang'
import FormItemLabel from '../FormItemLabel'
import { TimerPickerStyle } from './index.style'
import { Datepicker, setOptions } from '@mobiscroll/react'
import { useState, useCallback } from 'react'
import moment from 'moment'
import { Error } from '../../../../commonStyle/index.style'

setOptions({
  theme: 'ios',
  themeVariant: 'light'
})

function TimePicker ({
  name, onChange = () => {}, required,
  defaultValue = new Date(), error, minTime, maxTime
}) {
  const [selected, setSelected] = useState(defaultValue)

  const handleOnChange = useCallback((e) => {
    setSelected(e.value)
    onChange({
      name,
      value: moment(e.value).format('HH:MM')
    })
  }, [name, onChange])

  return (
    <TimerPickerStyle>
      <FormItemLabel
        title={LANG_STRINGS.selectTime}
        required={required}
      />
      <Datepicker
        controls={['time']}
        timeFormat='h:mm A'
        touchUi
        class='timer-label'
        returnFormat='moment'
        defaultValue={selected}
        onChange={handleOnChange}
        placeholder={LANG_STRINGS.select}
        min={minTime}
        max={maxTime}
      />
      <Error>{error}</Error>
    </TimerPickerStyle>
  )
}

export default TimePicker
