import { createRef, Component } from 'react'
import PropTypes from 'prop-types'
import NumberFormat from 'react-number-format'
import { NotificationManager } from 'react-notifications'
import { Modal, CustomText, Button } from '../../../../../components'
import Slider from '../../../../../components/Slider'
import { Row } from '../../../../../commonStyle/index.style'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { LANG_STRINGS, ERROR_LANG } from '../../../../../lang'
import { convertTo3digitFloat, formatMoney } from '../../../../../helpers/utility'
import { VehiclePriceEditStyle } from './index.style'

class VehiclePriceEditModal extends Component {
  static propTypes = {
    showEditModal: PropTypes.bool,
    value: PropTypes.number,
    initialPrice: PropTypes.number,
    onSubmit: PropTypes.func,
    onClose: PropTypes.func
  }

  constructor (props) {
    super(props)
    this.state = {
      amount: props.value || 0,
      minAmount: 0,
      maxAmount: 100
    }
    this.sliderRef = createRef()
  }

  componentDidMount () {
    this.updateMinMaxAmount()
  }

  updateMinMaxAmount = () => {
    // 30 is the variation in the amount that can be used to update
    // the amount by Agent/Mitra
    const minAmount = Math.ceil(this.props.initialPrice * 0.7) // -30%
    const maxAmount = Math.floor(this.props.initialPrice * 1.3) // +30%
    this.setState({ minAmount, maxAmount })
  }

  handleValueChange = (values) => {
    const { value } = values
    let amount = convertTo3digitFloat(value || 0)
    const { minAmount, maxAmount } = this.state
    if (amount < 0) {
      return amount ? NotificationManager.error(ERROR_LANG.enterAmountNotInRange) : null
    }

    if (amount < minAmount) {
      // amount = amount
    } else if (amount > maxAmount) {
      amount = maxAmount
    }

    this.setState({
      amount
    })
    const sliderRef = this.sliderRef.current
    sliderRef.updateSliderValue(amount)
  }

  handleSliderChange = (value) => {
    this.setState({
      amount: convertTo3digitFloat(value)
    })
  }

  handleSubmit = (amount) => {
    const { onSubmit } = this.props
    const { minAmount, maxAmount } = this.state
    if ((amount < minAmount) || (amount > maxAmount)) {
      // amount = amount
      NotificationManager.error(ERROR_LANG.enterAmountNotInRange)
      return false
    }
    onSubmit(amount)
  }

  getSliderMinMaxText = (title) => {
    return (
      <CustomText
        size='14px;'
        color={AgentColorPallette.black}
        top='10px'
        bottom='10px'
      >
        {title}
      </CustomText>
    )
  }

  render () {
    const { showEditModal, onClose } = this.props
    const { amount, maxAmount, minAmount } = this.state
    return (
      <Modal
        heading={LANG_STRINGS.vehiclePrice}
        isOpen={showEditModal}
        onClose={onClose}
      >
        <VehiclePriceEditStyle>
          <Row className='amount-input-container' align='center' justify='space-between'>
            <CustomText
              color={AgentColorPallette.black}
              size='14px'
            >
              {LANG_STRINGS.vehiclePrice}:
            </CustomText>
            <NumberFormat
              decimalScale={0}
              thousandSeparator='.'
              decimalSeparator=','
              prefix='Rp '
              className='amount-input'
              value={amount || ''}
              onValueChange={(data) => this.handleValueChange(data)}
              placeholder={LANG_STRINGS.vehiclePrice}
            />
          </Row>
          <Slider
            name='amount'
            max={maxAmount}
            min={minAmount}
            selectedValue={amount}
            ref={this.sliderRef}
            onChange={value => this.handleSliderChange(value)}
          />
          <Row justify='space-between'>
            {this.getSliderMinMaxText(formatMoney(minAmount, 0))}
            {this.getSliderMinMaxText(formatMoney(maxAmount, 0))}
          </Row>
          <Button
            onClick={() => this.handleSubmit(amount)}
            className='amount-submit-btn'
          >
            {LANG_STRINGS.save}
          </Button>
        </VehiclePriceEditStyle>
      </Modal>
    )
  }
}

export default VehiclePriceEditModal
