import { useEffect, useCallback, useImperativeHandle, useRef, useState, forwardRef } from 'react'
import { LANG_STRINGS } from '../../../../../../../lang/index'
import { typeValid } from '../../../../../../../helpers/validations'
import { VehiclePlateNumberStyle } from './index.style'
import VehiclePlateNumberBottomSheet from './VehiclePlateNumberBottomSheet'

function VehiclePlateNumber ({ disabled, getRegionCodeData, onChange = () => {}, defaultValue = {} }, parentRef) {
  const [error, setError] = useState({})
  const that = useRef({
    ...defaultValue
  })

  useImperativeHandle(parentRef, () => ({
    validatePlateNumber: () => {
      const errorMap = {}
      if (!that.current.region_code) {
        errorMap.region_code = LANG_STRINGS.required
      }
      // if (!that.current.vehicle_plate_no || !typeValid('vehicle_plate_no', that.current.vehicle_plate_no)) {
      //   errorMap.vehicle_plate_no = that.current.vehicle_plate_no ? ERROR_LANG.incorrectFormat : LANG_STRINGS.required
      // }
      setError(errorMap)
      if (!Object.keys(errorMap).length) {
        return that.current
      }
    }
  }))

  useEffect(() => {
    if ((!that.current.region_code || !that.current.vehicle_plate_no) && (defaultValue.region_code || defaultValue.vehicle_plate_no)) {
      that.current = {
        ...defaultValue
      }
    }
  }, [defaultValue])

  const handleChange = useCallback((data, type) => {
    that.current = {
      ...that.current,
      [type]: data
    }
    if (type === 'vehicle_plate_no' && data && !typeValid('vehicle_plate_no', that.current.vehicle_plate_no)) {
      return
    }
    onChange({
      [type]: (type === 'vehicle_plate_no') && data ? data?.replace(/\s/g, '') : data
    })
  }, [onChange])

  return (
    <VehiclePlateNumberStyle>
      <VehiclePlateNumberBottomSheet
        title={LANG_STRINGS.kode}
        data={getRegionCodeData}
        displayKey='region_code'
        dataKey='region_code'
        required
        disabled={disabled}
        onChange={(data) => handleChange(data, 'region_code')}
        error={error.region_code}
        defaultValue={defaultValue.region_code}
      />
    </VehiclePlateNumberStyle>
  )
}

export default forwardRef(VehiclePlateNumber)
