import { useState, useCallback, useEffect } from 'react'
import { CustomText } from '../../../../../../../components'
import { formatMoney } from '../../../../../../../helpers/utility'
import { LANG_STRINGS } from '../../../../../../../lang'
import VehiclePriceEditModal from '../../../../../Application/components/VehiclePriceEditModal'
import { VehiclePriceStyle, SelectContainer, SelectDrop, SelectInput, Label } from './index.style'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'

function VehiclePriceInput ({ amount, initialVehiclePrice, setVehicleUpdatedPrice, onChange = () => {} }) {
  const [showEditModal, setShowEditModal] = useState(false)
  const [price, setPrice] = useState(amount)

  useEffect(() => {
    setPrice(amount)
    if (setVehicleUpdatedPrice) {
      setVehicleUpdatedPrice(amount)
    }
  }, [amount, setVehicleUpdatedPrice])

  const toggleEditModal = useCallback(() => {
    setShowEditModal(prevShowEditModal => !prevShowEditModal)
  }, [])

  const handleSubmitPrice = useCallback((price) => {
    setPrice(price)
    setShowEditModal(false)
    if (setVehicleUpdatedPrice) {
      setVehicleUpdatedPrice(price)
    }
    onChange({
      vehicle_sum_insured: price
    })
  }, [onChange, setVehicleUpdatedPrice])

  return (
    <VehiclePriceStyle>
      {
        <>
          <SelectContainer className='auto-input-box'>
            <Label active={showEditModal || price}>
              {LANG_STRINGS.vehiclePrice}
            </Label>
            <SelectDrop onClick={toggleEditModal}>
              <SelectInput
                value={price ? formatMoney(price, '') : ''}
                isOptionContainerOpen={showEditModal}
                // onChange={selectInputChangeHandler}
              />
              <span className='edit-vehicle-price'>
                <i className='fas fa-pen' />
              </span>
            </SelectDrop>
          </SelectContainer>
          <CustomText
            size='0.7rem'
            color={AgentColorPallette.dodgerBlue}
            top='0.4rem'
            textAlign='center'
          >
            {LANG_STRINGS.youCanChangeThePrice}
          </CustomText>
        </>
      }
      {
        showEditModal && (
          <VehiclePriceEditModal
            showEditModal={showEditModal}
            value={price}
            initialPrice={initialVehiclePrice}
            onClose={toggleEditModal}
            onSubmit={handleSubmitPrice}
          />
        )
      }
    </VehiclePriceStyle>
  )
}

export default VehiclePriceInput
