import styled from 'styled-components'
import NumberFormat from 'react-number-format'
import { AgentColorPallette } from '../../../../configs/colorPallete'

export const InputWrapper = styled.div`
  position: relative;
  margin-top: ${(props) => props.top || ''};
  margin-bottom: ${(props) => props.bottom || ''};
`

export const InputRow = styled.div`
  display: flex;
  align-items: center;
  border-radius: 12px;
  border: 1px solid
    ${(props) => (props.error ? AgentColorPallette.darkerRed : AgentColorPallette.grey_eee)};
  height: 56px;
  padding: 0px 16px;
  gap: 2px;
  background: ${(props) =>
    props.disabled ? AgentColorPallette.grey_eee : AgentColorPallette.white};
`

export const Prefix = styled.span`
  color: ${(props) =>
    props.disabled ? AgentColorPallette.fontGrey : AgentColorPallette.darkCharcoal};
  font-size: 12px;
  font-weight: 500;
  line-height: 16px;
  white-space: nowrap;
  user-select: none;
  overflow: hidden;
  max-width: ${(props) => (props.active ? '36px' : '0px')};
  opacity: ${(props) => (props.active ? '1' : '0')};
  transition:
    max-width 0.3s ease,
    opacity 0.3s ease;
`

export const Input = styled(NumberFormat)`
  border: none;
  outline: none;
  flex: 1;
  background: transparent;
  min-width: 0;
  color: ${(props) =>
    props.disabled ? AgentColorPallette.fontGrey : AgentColorPallette.darkCharcoal};
  font-size: 12px;
  font-weight: 500;
  line-height: 16px;

  &:disabled {
    cursor: not-allowed;
  }

  ::placeholder {
    color: ${AgentColorPallette.fontGrey};
    font-size: 12px;
    font-weight: 500;
    line-height: 16px;
  }
`

export const Label = styled.label`
  padding: 0px;
  display: block;
  transform-origin: left top;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: calc(100% - 24px);
  position: absolute;
  left: 2px;
  top: ${(props) => (props.active ? '-8px' : '8px')};
  transform: translate(14px, 16px) scale(1);
  transition:
    top 0.5s,
    font-size 0.5s,
    font-weight 0.5s,
    text-transform 0.5s,
    letter-spacing 0.5s,
    line-height 0.5s;
  z-index: 1;
  pointer-events: none;
  color: ${AgentColorPallette.fontGrey};
  font-size: ${(props) => (props.active ? '8px' : '12px')};
  font-style: normal;
  font-weight: ${(props) => (props.active ? '800' : '500')};
  line-height: ${(props) => (props.active ? '10px' : '16px')};
  letter-spacing: ${(props) => (props.active ? '0.32px' : '')};
  text-transform: ${(props) => (props.active ? 'uppercase' : '')};
`
