import { useEffect, useRef, useState } from 'react'
import { Input as StyledInput, Label, InputWrapper } from './index.style'
import { LANG_STRINGS } from '../../../../lang'
import NumberFormat from 'react-number-format'

function InputNumber (props) {
  const { placeholder, onBlur, error, onChange, onClick, disabled, value, type, top, bottom } = props

  const [showLabel, setShowLabel] = useState(false)

  const ref = useRef(null)

  const onClickHandler = (e) => {
    setShowLabel(true)
    onClick && onClick()
  }

  const onChangeHandler = (e) => {
    onChange && onChange(e)
  }

  const handleClickOutside = (event) => {
    if (ref.current && !ref.current.contains(event.target)) {
      if (!value) {
        setShowLabel(false)
      }
    }
  }

  useEffect(() => {
    document.addEventListener('click', handleClickOutside, false)

    return () => {
      document.removeEventListener('click', handleClickOutside, false)
    }
  }, [
    value
  ])

  return (
    <InputWrapper ref={ref} top={top} bottom={bottom}>
      <Label active={showLabel || value}>
        {placeholder}
      </Label>
      {
        (type === 'amount') && (
          <StyledInput
            onClick={onClickHandler}
            thousandSeparator='.'
            decimalSeparator=','
            prefix='Rp '
            value={value}
            disabled={disabled}
            onValueChange={onChangeHandler}
            decimalScale={0}
            allowNegative={false}
            className=''
          />
        )
      }
      {
        !type && (
          <StyledInput
            onClick={onClickHandler}
            value={value}
            disabled={disabled}
            onValueChange={onChangeHandler}
            decimalScale={0}
            className=''
          />
        )
      }
    </InputWrapper>
  )
}

export default InputNumber
