import { useState, useCallback, useMemo, useRef, forwardRef, useEffect, useImperativeHandle, Fragment } from 'react'
import { createPortal } from 'react-dom'
import debounce from 'lodash/debounce'
import { AgentColorPallette } from '../../../../../../../../configs/colorPallete'
import { useShowAgentPIC } from '../../../../../../../../state/globalState/hooks/useGlobalContext'
import { LANG_STRINGS } from '../../../../../../../../lang'
import { ARROW_SELECTION, CALL_HELP, ITEM_NOT_FOUND, SEARCH } from '../../../../../../../../images'
import { CustomText } from '../../../../../../../../components'
import Heading from '../../../../../../../../components/Heading'
import BottomActionSheet from '../../../../../../../../components/BottomActionSheet'
import {
  AutoSearchStyleSheet,
  SelectContainer, SelectLabel, SelectInput, SelectDrop,
  SearchContainer, ListContainer, ListItemHeader, ListItem, NotFoundContainer
} from './index.style'

function VehiclePlateNumberBottomSheet ({
  data,
  name,
  displayKey,
  dataKey,
  defaultValue = {},
  disabled,
  error,
  isHideField,
  onChange = () => { },
  onCloseSheet,
  margin
}, parentRef) {
  const [show, setShow] = useState(false || isHideField)
  const [query, setQuery] = useState('')
  const [selectedValue, setSelectedValue] = useState(defaultValue && defaultValue[dataKey])
  const [displayValue, setDisplayValue] = useState(defaultValue && defaultValue[displayKey])

  const dataMatrix = useMemo(() => {
    const matrix = {}
    data.forEach((item) => {
      const isMatchingQuery = `${item[displayKey]}`.toLowerCase().indexOf(query.toLowerCase()) !== -1
      if (isMatchingQuery || !query) {
        const firstChar = item[dataKey][0]
        if (!matrix[firstChar]) matrix[firstChar] = []
        matrix[firstChar].push(item)
      }
    })
    return matrix
  }, [data, dataKey, displayKey, query])

  const that = useRef({ isEvent: false })
  const inputRef = useRef()
  const [, handleShowPicInfo] = useShowAgentPIC()

  useImperativeHandle(parentRef, () => ({
    resetSearch: (resetKeyName) => {
      if (resetKeyName === name) {
        setSelectedValue('')
        setDisplayValue('')
        onChange(null)
      }
    }
  }))

  useEffect(() => {
    if (!that.current.isEvent) {
      that.current.isEvent = true
      const el = document.getElementById('search-header')
      if (el) {
        el.addEventListener('focusin', (e) => {
          e.preventDefault()
          e.stopPropagation()
        })
      }
    }
  }, [])

  useEffect(() => {
    if (!selectedValue && defaultValue) {
      setSelectedValue(defaultValue[dataKey])
      setDisplayValue(defaultValue[displayKey])
    }
  }, [defaultValue, selectedValue, displayKey, dataKey])

  const handleCloseSheet = useCallback(() => {
    if (isHideField && onCloseSheet) {
      onCloseSheet()
    }
    setShow(false)
    setQuery('')
    inputRef.current.value = ''
  }, [onCloseSheet, isHideField])

  const handleSelected = useCallback((item) => {
    // set selectedValue item
    setSelectedValue(item[dataKey])
    setDisplayValue(item[displayKey])
    setShow(false)
    setQuery('')
    inputRef.current.value = ''
    onChange(item)
  }, [dataKey, displayKey, onChange])

  const renderNotFoundItem = useCallback(() => {
    return (
      <NotFoundContainer>
        <div>
          <img width='180px' src={ITEM_NOT_FOUND} alt='Not Found' />
        </div>
        <div>
          <CustomText
            color={AgentColorPallette.blackGrey}
            weight={700}
            size='1.5em'
            bottom='8px'
            textAlign='center'
          >
            {LANG_STRINGS.oops}
          </CustomText>
          <CustomText
            color={AgentColorPallette.blackGrey}
            size='0.9em'
            textAlign='center'
            bottom='1rem'
          >
            {LANG_STRINGS.weCouldNotFoundItem}
          </CustomText>
        </div>
        <Heading
          title={LANG_STRINGS.moreOptions}
          width='100%'
        />
        <button className='contact-us' onClick={() => handleShowPicInfo()}>
          <div>
            <img src={CALL_HELP} alt='Call Help' />
          </div>
          {LANG_STRINGS.contactUs}
        </button>
      </NotFoundContainer>
    )
  }, [handleShowPicInfo])

  const renderSearchItemContainer = useCallback(() => {
    if (!Object.keys(dataMatrix).length) {
      return renderNotFoundItem()
    }

    return (
      <ListContainer>
        {Object.keys(dataMatrix).map((firstChar) => (
          <Fragment key={firstChar}>
            <ListItemHeader>
              <span>{firstChar}</span>
            </ListItemHeader>
            {dataMatrix[firstChar].map((item) => (
              <ListItem
                key={item[dataKey]}
                active={selectedValue === item[dataKey]}
                onClick={() => handleSelected(item)}
              >
                <span>{item[displayKey]}</span>
              </ListItem>
            ))}
          </Fragment>
        ))}
      </ListContainer>
    )
  }, [dataMatrix, dataKey, displayKey, selectedValue, handleSelected, renderNotFoundItem])

  const handleOnChange = debounce((e) => {
    setQuery(e.target.value)
  }, 350)

  return (
    <AutoSearchStyleSheet error={error}>
      {!isHideField && (
        <>
          {
            <SelectContainer className={margin ? 'auto-input-box' : ''}>
              <SelectLabel active={show || displayValue}>
                {LANG_STRINGS.areaCode2}
              </SelectLabel>
              <SelectDrop disabled={disabled} onClick={(e) => {
                e.stopPropagation();
                setShow(true);
              }}>
                <SelectInput
                  value={displayValue}
                  isOptionContainerOpen={show}
                  readOnly
                />
                <img src={ARROW_SELECTION} alt="Select" />
              </SelectDrop>
            </SelectContainer>
          }
        </>)}
      {
        show && createPortal(
          <BottomActionSheet
            show={show}
            onCloseSheet={handleCloseSheet}
            zIndex={3}
            showHeader
            title={LANG_STRINGS.areaCode2}
            titleStyle={{ size: '0.8em', weight: 800 }}
            backGroundColor={AgentColorPallette.grey_eee}
          >
            <SearchContainer>
              <input
                className='search-input'
                placeholder={LANG_STRINGS.searchAreaCode2}
                onChange={handleOnChange}
                ref={inputRef}
              />
              <div className='search-icon'>
                <img src={SEARCH} alt='Search' />
              </div>
            </SearchContainer>
            {renderSearchItemContainer()}
          </BottomActionSheet>,
          document.getElementById('bottom-sheet-portal')
        )
      }
    </AutoSearchStyleSheet>
  )
}

export default forwardRef(VehiclePlateNumberBottomSheet)
