import { useCallback, useState, forwardRef, useRef, useImperativeHandle, useEffect } from 'react'
import { ERROR_LANG, LANG_STRINGS } from '../../../../../lang/index'
import { DisplayCircleIcon, Grid, Row } from '../../../../../commonStyle/index.style'
import { CustomText, Button } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { ACCESSORY_TYPE } from '../../../Application/constants'
import Input from '../../../../../components/DynamicFormV2/components/Input'
import InputNumber from '../../../../../components/DynamicFormV2/components/InputNumberV2'
import CustomCheckbox from '../../../../../components/CustomCheckbox'
import FormItemLabel from '../../../../../components/DynamicForm/components/FormItemLabel'
import ShowSnackbar from '../../../../../components/ShowNotification'
import { AccessoryCard, VehicleAccessoryStyle } from './index.style'

function VehicleAccessories ({ defaultAccessory, maxAmount, onChange, onManualClick = () => {} }, parentRef) {
  const [isModification, setIsModification] = useState(false)
  const [errorMap, setErrorMap] = useState({})
  const [accessories, setAccessories] = useState([{
    key: 'accessories1',
    sum_insured: '',
    name: '',
    accessory_type: 'standard'
  }])
  const isSetDefault = useRef(false)

  useImperativeHandle(parentRef, () => ({
    validateAccessory: () => {
      const error = {}
      if (!isModification) {
        return { isValid: true, accessories: [] }
      }
      let totalAccessoriesInsured = 0
      accessories.forEach(accessory => {
        if (accessory.accessory_type === 'standard') {
          // only standard accessory have 10% limit of total_sum_insured
          totalAccessoriesInsured += accessory.sum_insured
        }
        if (!accessory.name) {
          error[accessory.key] = LANG_STRINGS.required
        }
        if (!accessory.sum_insured && accessory.sum_insured !== 0) { // null or undefined
          error[accessory.key] = LANG_STRINGS.required
        }
      })
      setErrorMap(error)

      if (totalAccessoriesInsured > maxAmount) {
        ShowSnackbar.error({
          visible: true,
          text: ERROR_LANG.maximumSumInsuredForAccessories
        })
        return { isValid: false, accessories }
      }

      return {
        isValid: !Object.keys(error).length,
        accessories
      }
    }
  }))

  useEffect(() => {
    if (defaultAccessory && defaultAccessory.length && !isModification && !isSetDefault.current) {
      isSetDefault.current = true
      setAccessories(defaultAccessory)
      setIsModification(true)
    }
  }, [isModification, defaultAccessory])

  const handleSwitch = useCallback(() => {
    setIsModification(prevIsModification => {
      if (prevIsModification) {
        onChange({
          accessories: []
        })
      } else {
        onChange({
          accessories
        })
      }
      return !prevIsModification
    })
  }, [onChange, accessories])

  const handleChangeRadio = useCallback((data, index) => {
    setAccessories(oldAccessories => {
      oldAccessories[index].accessory_type = data.code
      const newAccessories = [...oldAccessories]
      onChange({
        accessories: newAccessories
      })
      return [...oldAccessories]
    })
  }, [onChange])

  const handleAdd = useCallback(() => {
    if (accessories.length < 15) {
      setAccessories(oldAccessories => {
        const newAccessories = [
          ...oldAccessories,
          {
            key: `accessories${accessories.length + 1}`,
            accessory_type: 'standard'
          }
        ]
        onChange({
          accessories: newAccessories
        })
        return newAccessories
      })
    }
  }, [accessories, onChange])

  const handleChangeAccessories = useCallback((e, index) => {
    setAccessories(oldAccessories => {
      oldAccessories[index].name = e.target.value
      const newAccessories = [...oldAccessories]
      onChange({
        accessories: newAccessories
      })
      return newAccessories
    })
  }, [onChange])

  const handleChangeSumInsured = useCallback((data, index) => {
    setAccessories(oldAccessories => {
      oldAccessories[index].sum_insured = data && Number(data?.value)
      const newAccessories = [...oldAccessories]
      onChange({ accessories: newAccessories })
      return newAccessories
    })
  }, [onChange])

  const removeAccessoryForm = useCallback((index) => {
    // remove the selected index from the array
    setAccessories(oldAccessories => {
      oldAccessories.splice(index, 1)
      const newAccessories = [...oldAccessories]
      onChange({ accessories: newAccessories })
      return newAccessories
    })
  }, [onChange])

  const renderAccessory = useCallback((index, item = {}, totalItems) => {
    return (
      <AccessoryCard key={item.key} id='accessoryContainer'>
        <Row
          className='accessory-count'
          bgColor={AgentColorPallette.fontLightGrey}
          justify='space-between'
          align='center'
        >
          <DisplayCircleIcon
            width='20px'
            height='20px'
            bgColor={AgentColorPallette.borderGrey}
          >
            <CustomText
              color={AgentColorPallette.white}
              size='0.6em'
              weight={800}
              bgColor='transparent'
            >
              {index + 1}
            </CustomText>
          </DisplayCircleIcon>
          {
            totalItems > 1 && (
              <CustomText
                color={AgentColorPallette.bloodRed}
                size='0.7em'
                weight={700}
                className='cursor'
                onClick={() => removeAccessoryForm(index)}
              >
                {LANG_STRINGS.remove}
              </CustomText>
            )
          }
        </Row>
        <FormItemLabel
          title={LANG_STRINGS.accessoriesType}
        />
        <Row align='center' justify='space-between' gap='30px' className='button-container'>
          <Button className={`select-buttons ${item.accessory_type === 'standard' ? 'selected' : ''}`} onClick={() => handleChangeRadio(ACCESSORY_TYPE[0], index)}>Standar</Button>
          <Button className={`select-buttons ${item.accessory_type === 'non-standard' ? 'selected' : ''}`} onClick={() => handleChangeRadio(ACCESSORY_TYPE[1], index)}>Non-Standar</Button>
        </Row>
        <Input
          error={errorMap[item.key]}
          placeholder={LANG_STRINGS.accessoriesName}
          value={item.name || ''}
          onChange={(e) => handleChangeAccessories(e, index)}
          className='button-container'
        />
        <InputNumber
          placeholder={LANG_STRINGS.accessoriesPrice}
          type='amount'
          value={item.sum_insured || ''}
          onChange={value => handleChangeSumInsured(value, index)}
          error={errorMap[item.key]}
          top='20px'
        />
      </AccessoryCard>
    )
  }, [
    handleChangeRadio, removeAccessoryForm,
    handleChangeSumInsured, handleChangeAccessories,
    errorMap
  ])

  return (
    <VehicleAccessoryStyle>
      <Grid
        gridColumn='10fr 1fr'
        gap='1rem'
        align='center'
      >
        <CustomText
          color={AgentColorPallette.blackGrey}
          size='0.85rem'
        >
          {LANG_STRINGS.selectThisOptionIfYourVehicleModifications}
        </CustomText>
        <CustomCheckbox
          color={AgentColorPallette.black}
          isChecked={isModification}
          onChange={handleSwitch}
        />
      </Grid>
      <CustomText
        color={AgentColorPallette.dodgerBlue}
        size='0.75em'
        weight={700}
        top='4px'
        bottom='5px'
      >
        {LANG_STRINGS.additionalFeesApply}
      </CustomText>
      {
        isModification && (
          <div id='accessory-container' className='docSlider-scroll'>
            {
              accessories.map((accessory, index) => renderAccessory(index, accessory, accessories.length))
            }
            {
              (accessories.length < 10) && (
                <Button className='add-button' onClick={handleAdd}>Tambah Modifikasi</Button>
              )
            }
            <CustomText color={AgentColorPallette.black} top='10px' size='0.8em'>
              {LANG_STRINGS.needCalculationsWithSpecialConditions}&nbsp;
              <span className='blue-text' onClick={onManualClick}>{LANG_STRINGS.manualOrder}.</span>
            </CustomText>
          </div>
        )
      }
      {
        !isModification && (
          <CustomText color={AgentColorPallette.black} top='10px' size='0.8em' bottom='20px'>
            {LANG_STRINGS.needCalculationsWithSpecialConditions}&nbsp;
            <span className='blue-text' onClick={onManualClick}>{LANG_STRINGS.manualOrder}.</span>
          </CustomText>
        )
      }
    </VehicleAccessoryStyle>
  )
}

export default forwardRef(VehicleAccessories)
