import { useState, useEffect } from 'react'
import { MultiYearStyle, YearButton, ButtonContainer, CoverageButton, CoverageButtonGroup, CoverageContainer, CoverageTitle, CoverageLabel, DisabledOverlay } from './index.style'

function MultiYear ({ disabled, onChange = () => {}, defaultValue }) {
  const [selected, setSelected] = useState(null)
  const [coverageSelections, setCoverageSelections] = useState([])
  useEffect(() => {
    if (defaultValue) {
      setSelected(defaultValue?.length)
      setCoverageSelections(defaultValue)
    }
  }, [defaultValue])

  const handleYearSelect = (num) => {
    setSelected(num)
    setCoverageSelections(
      Array.from({ length: num }, (_, i) => ({
        year: i + 1,
        package_type: 'car-protection-comprehensive'
      }))
    )
    onChange({
      year_based_package_type_map: Array.from({ length: num }, (_, i) => ({ year: i + 1, package_type: 'car-protection-comprehensive' })),
      package_type: num === 1 ? 'car-protection-comprehensive' : 'car-protection-multiyear'
    })
  }

  const handleCoverageSelect = (yearIndex, type) => {
    const newSelections = coverageSelections.map((entry, index) => {
      if (index === yearIndex - 1) {
        return { ...entry, package_type: type }
      } else if (index >= yearIndex && type === 'car-protection-tlo') {
        return { ...entry, package_type: 'car-protection-tlo' }
      }
      return entry
    })
    setCoverageSelections(newSelections)
    onChange({
      year_based_package_type_map: newSelections,
      package_type: selected === 1 ? newSelections[0].package_type === 'car-protection-comprehensive' ? 'car-protection-comprehensive' : 'car-protection-tlo' : 'car-protection-multiyear'
    })
  }

  return (
    <MultiYearStyle>
      {disabled ? (
        <DisabledOverlay>
          <ButtonContainer>
            {[1, 2, 3, 4, 5].map((num) => (
              <YearButton
                key={num}
                selected={selected === num}
                onClick={() => handleYearSelect(num)}
              >
                {num}
                <br />
                Tahun
              </YearButton>
            ))}
          </ButtonContainer>
          {selected && (
            <CoverageContainer>
              {coverageSelections.map(({ year, package_type }, index) => (
                <div key={year}>
                  <CoverageTitle>Perlindungan Tahun ke-{year}</CoverageTitle>
                  <CoverageButtonGroup>
                    <CoverageButton
                      selected={package_type === 'car-protection-comprehensive'}
                      disabled={index > 0 && coverageSelections[index - 1].package_type === 'car-protection-tlo'}
                      onClick={() => handleCoverageSelect(year, 'car-protection-comprehensive')}
                    >
                      Komprehensif
                    </CoverageButton>
                    <CoverageButton
                      selected={package_type === 'car-protection-tlo'}
                      onClick={() => handleCoverageSelect(year, 'car-protection-tlo')}
                    >
                      TLO
                    </CoverageButton>
                  </CoverageButtonGroup>
                  {index > 0 && coverageSelections[index - 1].package_type === 'car-protection-tlo' && (
                    <CoverageLabel>Tidak bisa diubah karena tahun sebelumnya memilih TLO</CoverageLabel>
                  )}
                </div>
              ))}
            </CoverageContainer>
          )}
        </DisabledOverlay>
      ) : (
        <>
          <ButtonContainer>
            {[1, 2, 3, 4, 5].map((num) => (
              <YearButton
                key={num}
                selected={selected === num}
                onClick={() => handleYearSelect(num)}
              >
                {num}
                <br />
                Tahun
              </YearButton>
            ))}
          </ButtonContainer>
          {selected && (
            <CoverageContainer>
              {coverageSelections.map(({ year, package_type }, index) => (
                <div key={year}>
                  <CoverageTitle>Perlindungan Tahun ke-{year}</CoverageTitle>
                  <CoverageButtonGroup>
                    <CoverageButton
                      selected={package_type === 'car-protection-comprehensive'}
                      disabled={index > 0 && coverageSelections[index - 1].package_type === 'car-protection-tlo'}
                      onClick={() => handleCoverageSelect(year, 'car-protection-comprehensive')}
                    >
                      Komprehensif
                    </CoverageButton>
                    <CoverageButton
                      selected={package_type === 'car-protection-tlo'}
                      onClick={() => handleCoverageSelect(year, 'car-protection-tlo')}
                    >
                      TLO
                    </CoverageButton>
                  </CoverageButtonGroup>
                  {index > 0 && coverageSelections[index - 1].package_type === 'car-protection-tlo' && (
                    <CoverageLabel>Tidak bisa diubah karena tahun sebelumnya memilih TLO</CoverageLabel>
                  )}
                </div>
              ))}
            </CoverageContainer>
          )}
        </>
      )}
    </MultiYearStyle>
  )
}

export default MultiYear
