import { useCallback, useState, useEffect, useRef } from 'react'
import moment from 'moment'
import Calendar from 'react-calendar'
import { Label } from '../../../DynamicFormV2/components/Input/index.style'
import BottomActionSheet from '../../../../components/BottomActionSheet'
import { Error } from '../../../../commonStyle/index.style'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import { DatePickerStyle, DatePickerCalendarContainer } from './index.style'

function DatePickerV3({
  label,
  name,
  minDate,
  maxDate,
  dateFormat = 'YYYY-MM-DD',
  displayFormat = 'DD/MM/YYYY',
  onChange = () => {},
  error,
  defaultValue,
  onClick,
  validator,
  disabled = false,
}) {
  const [selected, setSelected] = useState()
  const [showLabel, setShowLabel] = useState(false)
  const [showCalendar, setShowCalendar] = useState(false)
  const ref = useRef(null)

  // Convert string dates to Date objects
  const getMinDate = () => {
    if (!minDate) return null
    return moment(minDate, dateFormat).toDate()
  }

  const getMaxDate = () => {
    if (!maxDate) return null
    return moment(maxDate, dateFormat).toDate()
  }

  useEffect(() => {
    if (defaultValue) {
      const formattedDefaultValue = moment(defaultValue).format(dateFormat)
      if (formattedDefaultValue !== selected) {
        setSelected(formattedDefaultValue)
        if (typeof onChange === 'function') {
          onChange(formattedDefaultValue)
        }
      }
    }
  }, [name, dateFormat, defaultValue, selected, onChange])

  const handleOnChange = useCallback(
    (value) => {
      const formattedValue = moment(value).format(dateFormat)
      if (validator) {
        if (!validator(formattedValue)) {
        }
      }
      setSelected(formattedValue)
      onChange(formattedValue)
      onChange({ name, value: formattedValue })
      setShowCalendar(false)
    },
    [name, dateFormat, validator, onChange]
  )

  const onClickHandler = (e) => {
    if (disabled) return
    setShowLabel(true)
    setShowCalendar(true)
    onClick && onClick()
  }

  const handleClickOutside = useCallback(
    (event) => {
      if (ref.current && !ref.current.contains(event.target)) {
        if (!selected) {
          setShowLabel(false)
        }
      }
    },
    [selected]
  )

  useEffect(() => {
    document.addEventListener('click', handleClickOutside, false)
    return () => {
      document.removeEventListener('click', handleClickOutside, false)
    }
  }, [handleClickOutside])

  const getCalendarValue = () => {
    if (!selected) return null
    return moment(selected).toDate()
  }

  // Format date for display in input
  const getDisplayValue = () => {
    if (!selected) return ''
    return moment(selected).format(displayFormat)
  }

  return (
    <DatePickerStyle ref={ref} error={error} onClick={onClickHandler} disabled={disabled}>
      <Label active={selected || showLabel}>{label}</Label>
      <input
        className="md-mobile-picker-input"
        value={getDisplayValue()}
        readOnly
        disabled={disabled}
      />
      {error && <Error>{error}</Error>}
      <BottomActionSheet
        showHeader
        title={label}
        backGroundColor={AgentColorPallette.darkYellow}
        show={showCalendar}
        onCloseSheet={() => setShowCalendar(false)}
      >
        <DatePickerCalendarContainer>
          <Calendar
            minDetail="decade"
            maxDetail="month"
            defaultView="month"
            showNeighboringMonth={false}
            next2Label={null}
            prev2Label={null}
            minDate={getMinDate()}
            maxDate={getMaxDate()}
            value={getCalendarValue()}
            onChange={handleOnChange}
            tileClassName={({ date, view }) => {
              if (view === 'month' && date.getDay() === 0) {
                return 'sunday'
              }
            }}
            formatShortWeekday={(_locale, date) => {
              return new Intl.DateTimeFormat('id-ID', {
                weekday: 'long',
              })
                .format(date)
                .substring(0, 1)
            }}
          />
        </DatePickerCalendarContainer>
      </BottomActionSheet>
    </DatePickerStyle>
  )
}

export default DatePickerV3
